#include "cpp-example/cpp/include/example.h"

#include <fmt/format.h>

#include <charconv>
#include <stdexcept>
#include <string_view>
#include <system_error>

// Generated by cxx from src/bridge.rs: declares the Rust functions C++ may call.
#include "cpp-example/src/bridge.rs.h"

namespace cpp_example {
namespace {

std::string_view view(rust::Str text) { return {text.data(), text.size()}; }

}  // namespace

void Accumulator::add(double value) {
  sum_ += value;
  ++count_;
}

std::size_t Accumulator::count() const { return count_; }

double Accumulator::mean() const { return count_ == 0 ? 0.0 : sum_ / static_cast<double>(count_); }

std::unique_ptr<Accumulator> new_accumulator() { return std::make_unique<Accumulator>(); }

rust::String format_greeting(rust::Str name, std::uint32_t times) {
  // Calling back into Rust.
  log_from_cpp(fmt::format("format_greeting(name={}, times={})", view(name), times));
  // std::string converts to rust::String on return.
  return fmt::format("Hello, {}! Greeted {} time{} by C++ using {{fmt}} {}.{}.{}", view(name),
                     times, times == 1 ? "" : "s", FMT_VERSION / 10000, FMT_VERSION / 100 % 100,
                     FMT_VERSION % 100);
}

std::uint32_t parse_positive(rust::Str text) {
  const char* const first = text.data();
  const char* const last = first + text.size();
  std::uint32_t value = 0;
  const auto [end, error] = std::from_chars(first, last, value);
  if (error != std::errc{} || end != last || value == 0) {
    throw std::invalid_argument(fmt::format("not a positive integer: '{}'", view(text)));
  }
  return value;
}

}  // namespace cpp_example
